{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "keep",
  "supportive_card_ids": ["C43","C45","C48","C49","C50","C51","C57","C60","C63","C64","C80","C81"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C43","C45","C48","C49","C50","C51","C80","C81"],
  "claims": [
    {
      "claim": "The query SMILES corresponds to glipizide, a sulfonylurea; no direct absolute oral-bioavailability measurement for glipizide is present in the visible records, but L3 oral-exposure records for the closely related sulfonylureas glibenclamide (C43, C45) and glimepiride (C49, C50), for the sulfonylurea-loop diuretic torsemide (C48), and for the pyrazine-containing acipimox (C51) show measurable oral AUC/Cmax in humans, supporting class-level oral absorption consistent with F ≥ 20%.",
      "card_ids": ["C43","C45","C48","C49","C50","C51"]
    },
    {
      "claim": "L4 solubility/dissolution records show low intrinsic aqueous/SGF solubility for related sulfonylureas (C53, C56) but high solubility in surfactant vehicles and fast dissolution from formulations (C57, C60, C63, C64); low intrinsic solubility alone is not affirmative evidence of F < 20%.",
      "card_ids": ["C53","C56","C57","C60","C63","C64"]
    },
    {
      "claim": "L5 efflux records show glibenclamide is a moderate P-gp/BCRP substrate (C66, C69, C70, C71) and gliquidone is not an MRP1/MRP3 substrate (C65, C72); these are mechanistic analog findings, not direct F measurements, and do not affirm F < 20%.",
      "card_ids": ["C65","C66","C69","C70","C71","C72"]
    },
    {
      "claim": "L6 hepatic-clearance records show low CYP2C9 intrinsic clearance for tolbutamide (C81, C85, C88), poor microsomal turnover for the glimepiride metabolite M1 (C80), and reported HLM intrinsic clearance for glyburide (C82, C83, C86); these are mechanistic analog data, not direct F, and do not provide affirmative evidence of F < 20%; low intrinsic clearance/poor oxidative metabolism is consistent with limited first-pass.",
      "card_ids": ["C80","C81","C82","C83","C85","C86","C88"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "no_change",
      "card_ids": ["C77","C78","C79","C80","C81","C82","C83","C84","C85","C86","C87","C88"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral-bioavailability measurement for glipizide is present in the visible records.",
    "No query-specific permeability, efflux, or hepatic-clearance record is available; L3-L6 records are for related sulfonylureas and other molecules.",
    "Transfer from glibenclamide/glimepiride/torsemide/tolbutamide is structural/class-level rather than exact-condition matched.",
    "The impact of full ionization, high TPSA, and possible transporter-mediated absorption on glipizide F remains unresolved.",
    "L6 hepatic-clearance records are in vitro/recombinant and not direct F measurements; species and assay-system differences limit quantitative transfer."
  ],
  "decision_summary": "Predicted high (F ≥ 20%) because glipizide is a sulfonylurea with measurable oral exposure in closely related analogs and no affirmative low-F evidence; L6 hepatic-clearance records for related sulfonylureas are mechanistic and do not overturn the prior. Confidence remains moderate because no direct F or query-specific data are available."
}

